import{_ as i,o as r,c as n,U as t,a as s,e as a,f as c,g as d,i as l}from"./index-CBX5WtZH.js";const u={},h={class:"legal-doc"};function p(v,e){const o=l("RouterLink");return r(),n("div",h,[e[3]||(e[3]=t('<h1 data-v-ee42c634>PRIVACY POLICY</h1><p class="subtitle" data-v-ee42c634><strong data-v-ee42c634>Last updated</strong> April 05, 2026</p><p data-v-ee42c634> This Privacy Notice for <strong data-v-ee42c634>Aidan Boissonneault</strong> (doing business as <strong data-v-ee42c634>Terva</strong>) (&quot;we&quot;, &quot;us&quot;, or &quot;our&quot;), describes how and why we might access, collect, store, use, and/or share (&quot;process&quot;) your personal information when you use our services (&quot;Services&quot;), including when you: </p><ul data-v-ee42c634><li data-v-ee42c634>Visit our website at <a href="https://www.tervabrewed.com" target="_blank" rel="noopener" data-v-ee42c634>https://www.tervabrewed.com</a> or any website of ours that links to this Privacy Notice</li><li data-v-ee42c634>Download and use our mobile application (Terva), or any other application of ours that links to this Privacy Notice</li><li data-v-ee42c634>Use Terva. Terva is a specialty coffee brew tracking app that helps you log, refine, and revisit your brewing recipes. Track your beans, gear, and brew steps - and discover what makes each cup great.</li><li data-v-ee42c634>Engage with us in other related ways, including any sales, marketing, or events</li></ul><p data-v-ee42c634><strong data-v-ee42c634>Questions or concerns?</strong> Reading this Privacy Notice will help you understand your privacy rights and choices. We are responsible for making decisions about how your personal information is processed. If you do not agree with our policies and practices, please do not use our Services. If you still have any questions or concerns, please contact us at <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a>. </p><h2 data-v-ee42c634>SUMMARY OF KEY POINTS</h2><div class="summary-box" data-v-ee42c634><p data-v-ee42c634><strong data-v-ee42c634><em data-v-ee42c634>This summary provides key points from our Privacy Notice. You can find more details about any of these topics by clicking the links or using the <a href="#toc" data-v-ee42c634>table of contents</a> below.</em></strong></p><p data-v-ee42c634><strong data-v-ee42c634>What personal information do we process?</strong> When you visit, use, or navigate our Services, we may process personal information depending on how you interact with us and the Services, the choices you make, and the products and features you use. Learn more about <a href="#personalinfo" data-v-ee42c634>personal information you disclose to us</a>.</p><p data-v-ee42c634><strong data-v-ee42c634>Do we process any sensitive personal information?</strong> We do not process sensitive personal information.</p><p data-v-ee42c634><strong data-v-ee42c634>Do we collect any information from third parties?</strong> We do not collect any information from third parties.</p><p data-v-ee42c634><strong data-v-ee42c634>How do we process your information?</strong> We process your information to provide, improve, and administer our Services, communicate with you, for security and fraud prevention, and to comply with law. We may also process your information for other purposes with your consent. Learn more about <a href="#infouse" data-v-ee42c634>how we process your information</a>.</p><p data-v-ee42c634><strong data-v-ee42c634>In what situations and with which parties do we share personal information?</strong> We may share information in specific situations and with specific third parties. Learn more about <a href="#whoshare" data-v-ee42c634>when and with whom we share your personal information</a>.</p><p data-v-ee42c634><strong data-v-ee42c634>How do we keep your information safe?</strong> We have adequate organisational and technical processes and procedures in place to protect your personal information. However, no electronic transmission over the internet or information storage technology can be guaranteed to be 100% secure. Learn more about <a href="#infosafe" data-v-ee42c634>how we keep your information safe</a>.</p><p data-v-ee42c634><strong data-v-ee42c634>What are your rights?</strong> Depending on where you are located geographically, the applicable privacy law may mean you have certain rights regarding your personal information. Learn more about <a href="#privacyrights" data-v-ee42c634>your privacy rights</a>.</p><p data-v-ee42c634><strong data-v-ee42c634>How do you exercise your rights?</strong> The easiest way to exercise your rights is by visiting <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a> or by contacting us. We will consider and act upon any request in accordance with applicable data protection laws.</p><p data-v-ee42c634>Want to learn more about what we do with any information we collect? <a href="#toc" data-v-ee42c634>Review the Privacy Notice in full</a>.</p></div><h2 id="toc" data-v-ee42c634>TABLE OF CONTENTS</h2><nav class="toc" data-v-ee42c634><a href="#infocollect" data-v-ee42c634>1. What Information Do We Collect?</a><a href="#infouse" data-v-ee42c634>2. How Do We Process Your Information?</a><a href="#legalbases" data-v-ee42c634>3. What Legal Bases Do We Rely On To Process Your Personal Information?</a><a href="#whoshare" data-v-ee42c634>4. When And With Whom Do We Share Your Personal Information?</a><a href="#cookies" data-v-ee42c634>5. Do We Use Cookies And Other Tracking Technologies?</a><a href="#sociallogins" data-v-ee42c634>6. How Do We Handle Your Social Logins?</a><a href="#inforetain" data-v-ee42c634>7. How Long Do We Keep Your Information?</a><a href="#infosafe" data-v-ee42c634>8. How Do We Keep Your Information Safe?</a><a href="#infominors" data-v-ee42c634>9. Do We Collect Information From Minors?</a><a href="#privacyrights" data-v-ee42c634>10. What Are Your Privacy Rights?</a><a href="#DNT" data-v-ee42c634>11. Controls For Do-Not-Track Features</a><a href="#uslaws" data-v-ee42c634>12. Do United States Residents Have Specific Privacy Rights?</a><a href="#policyupdates" data-v-ee42c634>13. Do We Make Updates To This Notice?</a><a href="#contact" data-v-ee42c634>14. How Can You Contact Us About This Notice?</a><a href="#request" data-v-ee42c634>15. How Can You Review, Update, Or Delete The Data We Collect From You?</a></nav><h2 id="infocollect" data-v-ee42c634>1. WHAT INFORMATION DO WE COLLECT?</h2><h3 id="personalinfo" data-v-ee42c634>Personal information you disclose to us</h3><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> We collect personal information that you provide to us.</em></p><p data-v-ee42c634> We collect personal information that you voluntarily provide to us when you register on the Services, express an interest in obtaining information about us or our products and Services, when you participate in activities on the Services, or otherwise when you contact us. </p><p data-v-ee42c634><strong data-v-ee42c634>Personal Information Provided by You.</strong> The personal information we collect may include the following:</p><ul data-v-ee42c634><li data-v-ee42c634>Names</li><li data-v-ee42c634>Email addresses</li><li data-v-ee42c634>Passwords</li><li data-v-ee42c634>Contact or authentication data</li><li data-v-ee42c634>Debit/credit card numbers</li><li data-v-ee42c634>Billing addresses</li><li data-v-ee42c634>Usernames</li><li data-v-ee42c634>Contact preferences</li><li data-v-ee42c634>Coffee brewing data, recipes, and tasting notes</li></ul><p data-v-ee42c634><strong data-v-ee42c634>Sensitive Information.</strong> We do not process sensitive information.</p><p data-v-ee42c634><strong data-v-ee42c634>Payment Data.</strong> We may collect data necessary to process your payment if you choose to make purchases, such as your payment instrument number and the security code associated with your payment instrument. All payment data is handled and stored by <strong data-v-ee42c634>Stripe</strong>. You may find their privacy notice here: <a href="https://stripe.com/privacy" target="_blank" rel="noopener" data-v-ee42c634>https://stripe.com/privacy</a>. </p><p data-v-ee42c634><strong data-v-ee42c634>Social Media Login Data.</strong> We may provide you with the option to register with us using your existing social media account details. If you choose to register in this way, we will collect certain profile information about you from the social media provider, as described in the section <a href="#sociallogins" data-v-ee42c634>How Do We Handle Your Social Logins?</a> below. </p><p data-v-ee42c634><strong data-v-ee42c634>Application Data.</strong> If you use our application(s), we also may collect the following information if you choose to provide us with access or permission:</p><ul data-v-ee42c634><li data-v-ee42c634><em data-v-ee42c634>Mobile Device Access.</em> We may request access or permission to certain features from your mobile device, including bluetooth, camera, and other features. If you wish to change our access or permissions, you may do so in your device&#39;s settings.</li><li data-v-ee42c634><em data-v-ee42c634>Mobile Device Data.</em> We automatically collect device information (such as your mobile device ID, model, and manufacturer), operating system, version information and system configuration information, device and application identification numbers, browser type and version, hardware model, Internet service provider and/or mobile carrier, and Internet Protocol (IP) address. If you are using our application(s), we may also collect information about the phone network associated with your mobile device, the type of mobile device you use, your mobile device&#39;s unique device ID, and information about the features of our application(s) you accessed.</li><li data-v-ee42c634><em data-v-ee42c634>Push Notifications.</em> We may request to send you push notifications regarding your account or certain features of the application(s). If you wish to opt out from receiving these types of communications, you may turn them off in your device&#39;s settings.</li></ul><p data-v-ee42c634>This information is primarily needed to maintain the security and operation of our application(s), for troubleshooting, and for our internal analytics and reporting purposes.</p><p data-v-ee42c634>All personal information that you provide to us must be true, complete, and accurate, and you must notify us of any changes to such personal information.</p><h3 data-v-ee42c634>Information automatically collected</h3><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> Some information - such as your Internet Protocol (IP) address and/or browser and device characteristics - is collected automatically when you visit our Services.</em></p><p data-v-ee42c634> We automatically collect certain information when you visit, use, or navigate the Services. This information does not reveal your specific identity (like your name or contact information) but may include device and usage information, such as your IP address, browser and device characteristics, operating system, language preferences, referring URLs, device name, country, location, information about how and when you use our Services, and other technical information. This information is primarily needed to maintain the security and operation of our Services, and for our internal analytics and reporting purposes. </p><p data-v-ee42c634>Like many businesses, we also collect information through cookies and similar technologies.</p><p data-v-ee42c634>The information we collect includes:</p><ul data-v-ee42c634><li data-v-ee42c634><em data-v-ee42c634>Log and Usage Data.</em> Log and usage data is service-related, diagnostic, usage, and performance information our servers automatically collect when you access or use our Services and which we record in log files. Depending on how you interact with us, this log data may include your IP address, device information, browser type and settings, and information about your activity in the Services (such as the date/time stamps associated with your usage, pages and files viewed, searches, and other actions you take such as which features you use), device event information (such as system activity, error reports, and hardware settings).</li><li data-v-ee42c634><em data-v-ee42c634>Device Data.</em> We collect device data such as information about your computer, phone, tablet, or other device you use to access the Services. Depending on the device used, this device data may include information such as your IP address (or proxy server), device and application identification numbers, location, browser type, hardware model, Internet service provider and/or mobile carrier, operating system, and system configuration information.</li></ul><h3 data-v-ee42c634>Google API</h3><p data-v-ee42c634> Our use of information received from Google APIs will adhere to the <a href="https://developers.google.com/terms/api-services-user-data-policy" target="_blank" rel="noopener noreferrer" data-v-ee42c634>Google API Services User Data Policy</a>, including the <a href="https://developers.google.com/terms/api-services-user-data-policy#limited-use" target="_blank" rel="noopener noreferrer" data-v-ee42c634>Limited Use requirements</a>. </p><h2 id="infouse" data-v-ee42c634>2. HOW DO WE PROCESS YOUR INFORMATION?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> We process your information to provide, improve, and administer our Services, communicate with you, for security and fraud prevention, and to comply with law. We may also process your information for other purposes only with your prior explicit consent.</em></p><p data-v-ee42c634><strong data-v-ee42c634>We process your personal information for a variety of reasons, depending on how you interact with our Services, including:</strong></p><ul data-v-ee42c634><li data-v-ee42c634><strong data-v-ee42c634>To facilitate account creation and authentication and otherwise manage user accounts.</strong> We may process your information so you can create and log in to your account, as well as keep your account in working order.</li><li data-v-ee42c634><strong data-v-ee42c634>To deliver and facilitate delivery of services to the user.</strong> We may process your information to provide you with the requested service.</li><li data-v-ee42c634><strong data-v-ee42c634>To respond to user inquiries/offer support to users.</strong> We may process your information to respond to your inquiries and solve any potential issues you might have with the requested service.</li><li data-v-ee42c634><strong data-v-ee42c634>To send administrative information to you.</strong> We may process your information to send you details about our products and services, changes to our terms and policies, and other similar information.</li><li data-v-ee42c634><strong data-v-ee42c634>To fulfil and manage your orders.</strong> We may process your information to fulfil and manage your orders, payments, returns, and exchanges made through the Services.</li><li data-v-ee42c634><strong data-v-ee42c634>To request feedback.</strong> We may process your information when necessary to request feedback and to contact you about your use of our Services.</li><li data-v-ee42c634><strong data-v-ee42c634>To send you marketing and promotional communications.</strong> We may process the personal information you send to us for our marketing purposes, if this is in accordance with your marketing preferences. You can opt out of our marketing emails at any time. For more information, see <a href="#privacyrights" data-v-ee42c634>What Are Your Privacy Rights?</a> below.</li><li data-v-ee42c634><strong data-v-ee42c634>To protect our Services.</strong> We may process your information as part of our efforts to keep our Services safe and secure, including fraud monitoring and prevention.</li><li data-v-ee42c634><strong data-v-ee42c634>To identify usage trends.</strong> We may process information about how you use our Services to better understand how they are being used so we can improve them.</li><li data-v-ee42c634><strong data-v-ee42c634>To save or protect an individual&#39;s vital interest.</strong> We may process your information when necessary to save or protect an individual&#39;s vital interest, such as to prevent harm.</li></ul><h2 id="legalbases" data-v-ee42c634>3. WHAT LEGAL BASES DO WE RELY ON TO PROCESS YOUR INFORMATION?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> We only process your personal information when we believe it is necessary and we have a valid legal reason (i.e. legal basis) to do so under applicable law, like with your consent, to comply with laws, to provide you with services to enter into or fulfil our contractual obligations, to protect your rights, or to fulfil our legitimate business interests.</em></p><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634><u data-v-ee42c634>If you are located in the EU or UK, this section applies to you.</u></strong></em></p><p data-v-ee42c634>The General Data Protection Regulation (GDPR) and UK GDPR require us to explain the valid legal bases we rely on in order to process your personal information. As such, we may rely on the following legal bases to process your personal information:</p><ul data-v-ee42c634><li data-v-ee42c634><strong data-v-ee42c634>Consent.</strong> We may process your information if you have given us permission (i.e. consent) to use your personal information for a specific purpose. You can withdraw your consent at any time. Learn more about <a href="#withdrawconsent" data-v-ee42c634>withdrawing your consent</a>.</li><li data-v-ee42c634><strong data-v-ee42c634>Performance of a Contract.</strong> We may process your personal information when we believe it is necessary to fulfil our contractual obligations to you, including providing our Services or at your request prior to entering into a contract with you.</li><li data-v-ee42c634><strong data-v-ee42c634>Legitimate Interests.</strong> We may process your information when we believe it is reasonably necessary to achieve our legitimate business interests and those interests do not outweigh your interests and fundamental rights and freedoms. For example, we may process your personal information to: <ul class="indent" data-v-ee42c634><li data-v-ee42c634>Send users information about special offers and discounts on our products and services</li><li data-v-ee42c634>Analyse how our Services are used so we can improve them to engage and retain users</li><li data-v-ee42c634>Diagnose problems and/or prevent fraudulent activities</li><li data-v-ee42c634>Understand how our users use our products and services so we can improve user experience</li></ul></li><li data-v-ee42c634><strong data-v-ee42c634>Legal Obligations.</strong> We may process your information where we believe it is necessary for compliance with our legal obligations, such as to cooperate with a law enforcement body or regulatory agency, exercise or defend our legal rights, or disclose your information as evidence in litigation in which we are involved.</li><li data-v-ee42c634><strong data-v-ee42c634>Vital Interests.</strong> We may process your information where we believe it is necessary to protect your vital interests or the vital interests of a third party, such as situations involving potential threats to the safety of any person.</li></ul><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634><u data-v-ee42c634>If you are located in Canada, this section applies to you.</u></strong></em></p><p data-v-ee42c634> We may process your information if you have given us specific permission (i.e. express consent) to use your personal information for a specific purpose, or in situations where your permission can be inferred (i.e. implied consent). You can <a href="#withdrawconsent" data-v-ee42c634>withdraw your consent</a> at any time. </p><p data-v-ee42c634>In some exceptional cases, we may be legally permitted under applicable law to process your information without your consent, including, for example:</p><ul data-v-ee42c634><li data-v-ee42c634>If collection is clearly in the interests of an individual and consent cannot be obtained in a timely way</li><li data-v-ee42c634>For investigations and fraud detection and prevention</li><li data-v-ee42c634>For business transactions provided certain conditions are met</li><li data-v-ee42c634>If it is contained in a witness statement and the collection is necessary to assess, process, or settle an insurance claim</li><li data-v-ee42c634>For identifying injured, ill, or deceased persons and communicating with next of kin</li><li data-v-ee42c634>If we have reasonable grounds to believe an individual has been, is, or may be victim of financial abuse</li><li data-v-ee42c634>If it is reasonable to expect collection and use with consent would compromise the availability or the accuracy of the information and the collection is reasonable for purposes related to investigating a breach of an agreement or a contravention of the laws of Canada or a province</li><li data-v-ee42c634>If disclosure is required to comply with a subpoena, warrant, court order, or rules of the court relating to the production of records</li><li data-v-ee42c634>If it was produced by an individual in the course of their employment, business, or profession and the collection is consistent with the purposes for which the information was produced</li><li data-v-ee42c634>If the collection is solely for journalistic, artistic, or literary purposes</li><li data-v-ee42c634>If the information is publicly available and is specified by the regulations</li><li data-v-ee42c634>We may disclose de-identified information for approved research or statistics projects, subject to ethics oversight and confidentiality commitments</li></ul><h2 id="whoshare" data-v-ee42c634>4. WHEN AND WITH WHOM DO WE SHARE YOUR PERSONAL INFORMATION?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> We may share information in specific situations described in this section and/or with the following third parties.</em></p><p data-v-ee42c634><strong data-v-ee42c634>Vendors, Consultants, and Other Third-Party Service Providers.</strong> We may share your data with third-party vendors, service providers, contractors, or agents (&quot;third parties&quot;) who perform services for us or on our behalf and require access to such information to do that work. We have contracts in place with our third parties, which are designed to help safeguard your personal information. This means that they cannot do anything with your personal information unless we have instructed them to do it. They will also not share your personal information with any organisation apart from us. They also commit to protect the data they hold on our behalf and to retain it for the period we instruct. </p><p data-v-ee42c634>The third parties we may share personal information with are as follows:</p><ul data-v-ee42c634><li data-v-ee42c634><strong data-v-ee42c634>Allow Users to Connect to Their Third-Party Accounts</strong><br data-v-ee42c634>Google account</li><li data-v-ee42c634><strong data-v-ee42c634>Invoice and Billing</strong><br data-v-ee42c634>Stripe</li><li data-v-ee42c634><strong data-v-ee42c634>Web and Mobile Analytics</strong><br data-v-ee42c634>Google Analytics</li><li data-v-ee42c634><strong data-v-ee42c634>Website Performance Monitoring</strong><br data-v-ee42c634>Sentry</li><li data-v-ee42c634><strong data-v-ee42c634>User Account Registration &amp; Authentication</strong><br data-v-ee42c634>BetterAuth</li><li data-v-ee42c634><strong data-v-ee42c634>Web Hosting</strong><br data-v-ee42c634>Hostinger</li></ul><p data-v-ee42c634>We also may need to share your personal information in the following situations:</p><ul data-v-ee42c634><li data-v-ee42c634><strong data-v-ee42c634>Business Transfers.</strong> We may share or transfer your information in connection with, or during negotiations of, any merger, sale of company assets, financing, or acquisition of all or a portion of our business to another company.</li></ul><h2 id="cookies" data-v-ee42c634>5. DO WE USE COOKIES AND OTHER TRACKING TECHNOLOGIES?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> We may use cookies and other tracking technologies to collect and store your information.</em></p><p data-v-ee42c634> We may use cookies and similar tracking technologies (like web beacons and pixels) to gather information when you interact with our Services. Some online tracking technologies help us maintain the security of our Services and your account, prevent crashes, fix bugs, save your preferences, and assist with basic site functions. </p><p data-v-ee42c634> We also permit third parties and service providers to use online tracking technologies on our Services for analytics and advertising, including to help manage and display advertisements, to tailor advertisements to your interests, or to send abandoned shopping cart reminders (depending on your communication preferences). The third parties and service providers use their technology to provide advertising about products and services tailored to your interests which may appear either on our Services or on other websites. </p><p data-v-ee42c634> To the extent these online tracking technologies are deemed to be a &quot;sale&quot;/&quot;sharing&quot; (which includes targeted advertising, as defined under the applicable laws) under applicable US state laws, you can opt out of these online tracking technologies by submitting a request as described below under section <a href="#uslaws" data-v-ee42c634>Do United States Residents Have Specific Privacy Rights?</a></p>',55)),s("p",null,[e[1]||(e[1]=a(" Specific information about how we use such technologies and how you can refuse certain cookies is set out in our ",-1)),c(o,{to:"/cookies"},{default:d(()=>[...e[0]||(e[0]=[a("Cookie Notice",-1)])]),_:1}),e[2]||(e[2]=a(". ",-1))]),e[4]||(e[4]=t('<h2 id="sociallogins" data-v-ee42c634>6. HOW DO WE HANDLE YOUR SOCIAL LOGINS?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> If you choose to register or log in to our Services using a social media account, we may have access to certain information about you.</em></p><p data-v-ee42c634> Our Services offer you the ability to register and log in using your third-party social media account details (like your Facebook or X logins). Where you choose to do this, we will receive certain profile information about you from your social media provider. The profile information we receive may vary depending on the social media provider concerned, but will often include your name, email address, friends list, and profile picture, as well as other information you choose to make public on such a social media platform. </p><p data-v-ee42c634> We will use the information we receive only for the purposes that are described in this Privacy Notice or that are otherwise made clear to you on the relevant Services. Please note that we do not control, and are not responsible for, other uses of your personal information by your third-party social media provider. We recommend that you review their privacy notice to understand how they collect, use, and share your personal information, and how you can set your privacy preferences on their sites and apps. </p><h2 id="inforetain" data-v-ee42c634>7. HOW LONG DO WE KEEP YOUR INFORMATION?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> We keep your information for as long as necessary to fulfil the purposes outlined in this Privacy Notice unless otherwise required by law.</em></p><p data-v-ee42c634> We will only keep your personal information for as long as it is necessary for the purposes set out in this Privacy Notice, unless a longer retention period is required or permitted by law (such as tax, accounting, or other legal requirements). No purpose in this notice will require us keeping your personal information for longer than the period of time in which users have an account with us. </p><p data-v-ee42c634> When we have no ongoing legitimate business need to process your personal information, we will either delete or anonymise such information, or, if this is not possible (for example, because your personal information has been stored in backup archives), then we will securely store your personal information and isolate it from any further processing until deletion is possible. </p><h2 id="infosafe" data-v-ee42c634>8. HOW DO WE KEEP YOUR INFORMATION SAFE?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> We aim to protect your personal information through a system of organisational and technical security measures.</em></p><p data-v-ee42c634> We have implemented appropriate and reasonable technical and organisational security measures designed to protect the security of any personal information we process. However, despite our safeguards and efforts to secure your information, no electronic transmission over the Internet or information storage technology can be guaranteed to be 100% secure, so we cannot promise or guarantee that hackers, cybercriminals, or other unauthorised third parties will not be able to defeat our security and improperly collect, access, steal, or modify your information. Although we will do our best to protect your personal information, transmission of personal information to and from our Services is at your own risk. You should only access the Services within a secure environment. </p><h2 id="infominors" data-v-ee42c634>9. DO WE COLLECT INFORMATION FROM MINORS?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> We do not knowingly collect data from or market to children under 18 years of age or the equivalent age as specified by law in your jurisdiction.</em></p><p data-v-ee42c634> We do not knowingly collect, solicit data from, or market to children under 18 years of age, nor do we knowingly sell such personal information. By using the Services, you represent that you are at least 18 or that you are the parent or guardian of such a minor and consent to such minor dependent&#39;s use of the Services. If we learn that personal information from users less than 18 years of age has been collected, we will deactivate the account and take reasonable measures to promptly delete such data from our records. If you become aware of any data we may have collected from children under age 18, please contact us at <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a>. </p><h2 id="privacyrights" data-v-ee42c634>10. WHAT ARE YOUR PRIVACY RIGHTS?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> Depending on your state of residence in the US or in some regions, such as the European Economic Area (EEA), United Kingdom (UK), Switzerland, and Canada, you have rights that allow you greater access to and control over your personal information. You may review, change, or terminate your account at any time, depending on your country, province, or state of residence.</em></p><p data-v-ee42c634> In some regions (like the EEA, UK, Switzerland, and Canada), you have certain rights under applicable data protection laws. These may include the right (i) to request access and obtain a copy of your personal information, (ii) to request rectification or erasure; (iii) to restrict the processing of your personal information; (iv) if applicable, to data portability; and (v) not to be subject to automated decision-making. If a decision that produces legal or similarly significant effects is made solely by automated means, we will inform you, explain the main factors, and offer a simple way to request human review. In certain circumstances, you may also have the right to object to the processing of your personal information. You can make such a request by contacting us using the contact details provided in the section <a href="#contact" data-v-ee42c634>How Can You Contact Us About This Notice?</a> below. </p><p data-v-ee42c634>We will consider and act upon any request in accordance with applicable data protection laws.</p><p data-v-ee42c634> If you are located in the EEA or UK and you believe we are unlawfully processing your personal information, you also have the right to complain to your <a href="https://ec.europa.eu/justice/data-protection/bodies/authorities/index_en.htm" target="_blank" rel="noopener noreferrer" data-v-ee42c634>Member State data protection authority</a> or <a href="https://ico.org.uk/make-a-complaint/data-protection-complaints/data-protection-complaints/" target="_blank" rel="noopener noreferrer" data-v-ee42c634>UK data protection authority</a>. </p><p data-v-ee42c634> If you are located in Switzerland, you may contact the <a href="https://www.edoeb.admin.ch/edoeb/en/home.html" target="_blank" rel="noopener noreferrer" data-v-ee42c634>Federal Data Protection and Information Commissioner</a>. </p><p id="withdrawconsent" data-v-ee42c634><strong data-v-ee42c634><u data-v-ee42c634>Withdrawing your consent:</u></strong> If we are relying on your consent to process your personal information, you have the right to withdraw your consent at any time. You can withdraw your consent at any time by contacting us using the contact details provided in the section <a href="#contact" data-v-ee42c634>How Can You Contact Us About This Notice?</a> below or updating your preferences. </p><p data-v-ee42c634> However, please note that this will not affect the lawfulness of the processing before its withdrawal nor, when applicable law allows, will it affect the processing of your personal information conducted in reliance on lawful processing grounds other than consent. </p><p data-v-ee42c634><strong data-v-ee42c634><u data-v-ee42c634>Opting out of marketing and promotional communications:</u></strong> You can unsubscribe from our marketing and promotional communications at any time by clicking on the unsubscribe link in the emails that we send, or by contacting us using the details provided in the section <a href="#contact" data-v-ee42c634>How Can You Contact Us About This Notice?</a> below. You will then be removed from the marketing lists. However, we may still communicate with you - for example, to send you service-related messages that are necessary for the administration and use of your account, to respond to service requests, or for other non-marketing purposes. </p><h3 data-v-ee42c634>Account Information</h3><p data-v-ee42c634>If you would at any time like to review or change the information in your account or terminate your account, you can:</p><ul data-v-ee42c634><li data-v-ee42c634>Log in to your account settings and update your user account.</li><li data-v-ee42c634>Contact us using the contact information provided.</li></ul><p data-v-ee42c634> Upon your request to terminate your account, we will deactivate or delete your account and information from our active databases. However, we may retain some information in our files to prevent fraud, troubleshoot problems, assist with any investigations, enforce our legal terms and/or comply with applicable legal requirements. </p><p data-v-ee42c634><strong data-v-ee42c634><u data-v-ee42c634>Cookies and similar technologies:</u></strong> Most Web browsers are set to accept cookies by default. If you prefer, you can usually choose to set your browser to remove cookies and to reject cookies. If you choose to remove cookies or reject cookies, this could affect certain features or services of our Services. </p><p data-v-ee42c634> If you have questions or comments about your privacy rights, you may email us at <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a>. </p><h2 id="DNT" data-v-ee42c634>11. CONTROLS FOR DO-NOT-TRACK FEATURES</h2><p data-v-ee42c634> Most web browsers and some mobile operating systems and mobile applications include a Do-Not-Track (&quot;DNT&quot;) feature or setting you can activate to signal your privacy preference not to have data about your online browsing activities monitored and collected. At this stage, no uniform technology standard for recognising and implementing DNT signals has been finalised. As such, we do not currently respond to DNT browser signals or any other mechanism that automatically communicates your choice not to be tracked online. If a standard for online tracking is adopted that we must follow in the future, we will inform you about that practice in a revised version of this Privacy Notice. </p><p data-v-ee42c634> California law requires us to let you know how we respond to web browser DNT signals. Because there currently is not an industry or legal standard for recognising or honouring DNT signals, we do not respond to them at this time. </p><h2 id="uslaws" data-v-ee42c634>12. DO UNITED STATES RESIDENTS HAVE SPECIFIC PRIVACY RIGHTS?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> If you are a resident of California, Colorado, Connecticut, Delaware, Florida, Indiana, Iowa, Kentucky, Maryland, Minnesota, Montana, Nebraska, New Hampshire, New Jersey, Oregon, Rhode Island, Tennessee, Texas, Utah, or Virginia, you may have the right to request access to and receive details about the personal information we maintain about you and how we have processed it, correct inaccuracies, get a copy of, or delete your personal information. You may also have the right to withdraw your consent to our processing of your personal information. These rights may be limited in some circumstances by applicable law. More information is provided below.</em></p><h3 data-v-ee42c634>Categories of Personal Information We Collect</h3><p data-v-ee42c634> The table below shows the categories of personal information we have collected in the past twelve (12) months. For a comprehensive inventory of all personal information we process, please refer to the section <a href="#infocollect" data-v-ee42c634>What Information Do We Collect?</a></p><table data-v-ee42c634><thead data-v-ee42c634><tr data-v-ee42c634><th style="width:40%;" data-v-ee42c634>Category</th><th style="width:45%;" data-v-ee42c634>Examples</th><th style="width:15%;" data-v-ee42c634>Collected</th></tr></thead><tbody data-v-ee42c634><tr data-v-ee42c634><td data-v-ee42c634>A. Identifiers</td><td data-v-ee42c634>Contact details, such as real name, alias, postal address, telephone or mobile contact number, unique personal identifier, online identifier, Internet Protocol address, email address, and account name</td><td class="centered" data-v-ee42c634>YES</td></tr><tr data-v-ee42c634><td data-v-ee42c634>B. Personal information as defined in the California Customer Records statute</td><td data-v-ee42c634>Name, contact information, education, employment, employment history, and financial information</td><td class="centered" data-v-ee42c634>YES</td></tr><tr data-v-ee42c634><td data-v-ee42c634>C. Protected classification characteristics under state or federal law</td><td data-v-ee42c634>Gender, age, date of birth, race and ethnicity, national origin, marital status, and other demographic data</td><td class="centered" data-v-ee42c634>NO</td></tr><tr data-v-ee42c634><td data-v-ee42c634>D. Commercial information</td><td data-v-ee42c634>Transaction information, purchase history, financial details, and payment information</td><td class="centered" data-v-ee42c634>YES</td></tr><tr data-v-ee42c634><td data-v-ee42c634>E. Biometric information</td><td data-v-ee42c634>Fingerprints and voiceprints</td><td class="centered" data-v-ee42c634>NO</td></tr><tr data-v-ee42c634><td data-v-ee42c634>F. Internet or other similar network activity</td><td data-v-ee42c634>Browsing history, search history, online behaviour, interest data, and interactions with our and other websites, applications, systems, and advertisements</td><td class="centered" data-v-ee42c634>YES</td></tr><tr data-v-ee42c634><td data-v-ee42c634>G. Geolocation data</td><td data-v-ee42c634>Device location</td><td class="centered" data-v-ee42c634>NO</td></tr><tr data-v-ee42c634><td data-v-ee42c634>H. Audio, electronic, sensory, or similar information</td><td data-v-ee42c634>Images and audio, video or call recordings created in connection with our business activities</td><td class="centered" data-v-ee42c634>NO</td></tr><tr data-v-ee42c634><td data-v-ee42c634>I. Professional or employment-related information</td><td data-v-ee42c634>Business contact details in order to provide you our Services at a business level or job title, work history, and professional qualifications if you apply for a job with us</td><td class="centered" data-v-ee42c634>NO</td></tr><tr data-v-ee42c634><td data-v-ee42c634>J. Education information</td><td data-v-ee42c634>Student records and directory information</td><td class="centered" data-v-ee42c634>NO</td></tr><tr data-v-ee42c634><td data-v-ee42c634>K. Inferences drawn from collected personal information</td><td data-v-ee42c634>Inferences drawn from any of the collected personal information listed above to create a profile or summary about, for example, an individual&#39;s preferences and characteristics</td><td class="centered" data-v-ee42c634>NO</td></tr><tr data-v-ee42c634><td data-v-ee42c634>L. Sensitive personal information</td><td data-v-ee42c634></td><td class="centered" data-v-ee42c634>NO</td></tr></tbody></table><p data-v-ee42c634>We may also collect other personal information outside of these categories through instances where you interact with us in person, online, or by phone or mail in the context of:</p><ul data-v-ee42c634><li data-v-ee42c634>Receiving help through our customer support channels;</li><li data-v-ee42c634>Participation in customer surveys or contests; and</li><li data-v-ee42c634>Facilitation in the delivery of our Services and to respond to your inquiries.</li></ul><p data-v-ee42c634>We will use and retain the collected personal information as needed to provide the Services or for:</p><ul data-v-ee42c634><li data-v-ee42c634>Category A – As long as the user has an account with us</li><li data-v-ee42c634>Category B – As long as the user has an account with us</li><li data-v-ee42c634>Category D – As long as the user has an account with us</li><li data-v-ee42c634>Category F – As long as the user has an account with us</li></ul><h3 data-v-ee42c634>Sources of Personal Information</h3><p data-v-ee42c634>Learn more about the sources of personal information we collect in <a href="#infocollect" data-v-ee42c634>What Information Do We Collect?</a></p><h3 data-v-ee42c634>How We Use and Share Personal Information</h3><p data-v-ee42c634>Learn more about how we use your personal information in the section <a href="#infouse" data-v-ee42c634>How Do We Process Your Information?</a></p><p data-v-ee42c634><strong data-v-ee42c634>Will your information be shared with anyone else?</strong></p><p data-v-ee42c634> We may disclose your personal information with our service providers pursuant to a written contract between us and each service provider. Learn more about how we disclose personal information in the section <a href="#whoshare" data-v-ee42c634>When And With Whom Do We Share Your Personal Information?</a></p><p data-v-ee42c634> We may use your personal information for our own business purposes, such as for undertaking internal research for technological development and demonstration. This is not considered to be &quot;selling&quot; of your personal information. </p><p data-v-ee42c634> We have not sold or shared any personal information to third parties for a business or commercial purpose in the preceding twelve (12) months. The categories of third parties to whom we disclosed personal information for a business or commercial purpose can be found under <a href="#whoshare" data-v-ee42c634>When And With Whom Do We Share Your Personal Information?</a></p><h3 data-v-ee42c634>Your Rights</h3><p data-v-ee42c634>You have rights under certain US state data protection laws. However, these rights are not absolute, and in certain cases, we may decline your request as permitted by law. These rights include:</p><ul data-v-ee42c634><li data-v-ee42c634><strong data-v-ee42c634>Right to know</strong> whether or not we are processing your personal data</li><li data-v-ee42c634><strong data-v-ee42c634>Right to access</strong> your personal data</li><li data-v-ee42c634><strong data-v-ee42c634>Right to correct</strong> inaccuracies in your personal data</li><li data-v-ee42c634><strong data-v-ee42c634>Right to request</strong> the deletion of your personal data</li><li data-v-ee42c634><strong data-v-ee42c634>Right to obtain a copy</strong> of the personal data you previously shared with us</li><li data-v-ee42c634><strong data-v-ee42c634>Right to non-discrimination</strong> for exercising your rights</li><li data-v-ee42c634><strong data-v-ee42c634>Right to opt out</strong> of the processing of your personal data if it is used for targeted advertising (or sharing as defined under California&#39;s privacy law), the sale of personal data, or profiling in furtherance of decisions that produce legal or similarly significant effects (&quot;profiling&quot;)</li></ul><p data-v-ee42c634>Depending upon the state where you live, you may also have the following rights:</p><ul data-v-ee42c634><li data-v-ee42c634>Right to access the categories of personal data being processed (as permitted by applicable law, including the privacy law in Minnesota)</li><li data-v-ee42c634>Right to obtain a list of the categories of third parties to which we have disclosed personal data (as permitted by applicable law, including the privacy law in California, Delaware, and Maryland)</li><li data-v-ee42c634>Right to obtain a list of specific third parties to which we have disclosed personal data (as permitted by applicable law, including the privacy law in Minnesota and Oregon)</li><li data-v-ee42c634>Right to obtain a list of third parties to which we have sold personal data (as permitted by applicable law, including the privacy law in Connecticut)</li><li data-v-ee42c634>Right to review, understand, question, and depending on where you live, correct how personal data has been profiled (as permitted by applicable law, including the privacy law in Connecticut and Minnesota)</li><li data-v-ee42c634>Right to limit use and disclosure of sensitive personal data (as permitted by applicable law, including the privacy law in California)</li><li data-v-ee42c634>Right to opt out of the collection of sensitive data and personal data collected through the operation of a voice or facial recognition feature (as permitted by applicable law, including the privacy law in Florida)</li></ul><h3 data-v-ee42c634>How to Exercise Your Rights</h3><p data-v-ee42c634> To exercise these rights, you can contact us by visiting <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a>, by emailing us at <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a>, or by referring to the contact details at the bottom of this document. </p><p data-v-ee42c634> Under certain US state data protection laws, you can designate an authorised agent to make a request on your behalf. We may deny a request from an authorised agent that does not submit proof that they have been validly authorised to act on your behalf in accordance with applicable laws. </p><h3 data-v-ee42c634>Request Verification</h3><p data-v-ee42c634> Upon receiving your request, we will need to verify your identity to determine you are the same person about whom we have the information in our system. We will only use personal information provided in your request to verify your identity or authority to make the request. However, if we cannot verify your identity from the information already maintained by us, we may request that you provide additional information for the purposes of verifying your identity and for security or fraud-prevention purposes. </p><p data-v-ee42c634> If you submit the request through an authorised agent, we may need to collect additional information to verify your identity before processing your request and the agent will need to provide a written and signed permission from you to submit such request on your behalf. </p><h3 data-v-ee42c634>Appeals</h3><p data-v-ee42c634> Under certain US state data protection laws, if we decline to take action regarding your request, you may appeal our decision by emailing us at <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a>. We will inform you in writing of any action taken or not taken in response to the appeal, including a written explanation of the reasons for the decisions. If your appeal is denied, you may submit a complaint to your state attorney general. </p><h3 data-v-ee42c634>California &quot;Shine The Light&quot; Law</h3><p data-v-ee42c634> California Civil Code Section 1798.83, also known as the &quot;Shine The Light&quot; law, permits our users who are California residents to request and obtain from us, once a year and free of charge, information about categories of personal information (if any) we disclosed to third parties for direct marketing purposes and the names and addresses of all third parties with which we shared personal information in the immediately preceding calendar year. If you are a California resident and would like to make such a request, please submit your request in writing to us by using the contact details provided in the section <a href="#contact" data-v-ee42c634>How Can You Contact Us About This Notice?</a></p><h2 id="policyupdates" data-v-ee42c634>13. DO WE MAKE UPDATES TO THIS NOTICE?</h2><p data-v-ee42c634><em data-v-ee42c634><strong data-v-ee42c634>In Short:</strong> Yes, we will update this notice as necessary to stay compliant with relevant laws.</em></p><p data-v-ee42c634> We may update this Privacy Notice from time to time. The updated version will be indicated by an updated &quot;Revised&quot; date at the top of this Privacy Notice. If we make material changes to this Privacy Notice, we may notify you either by prominently posting a notice of such changes or by directly sending you a notification. We encourage you to review this Privacy Notice frequently to be informed of how we are protecting your information. </p><h2 id="contact" data-v-ee42c634>14. HOW CAN YOU CONTACT US ABOUT THIS NOTICE?</h2><p data-v-ee42c634> If you have questions or comments about this notice, you may email us at <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a> or contact us by post at: </p><div class="contact-block" data-v-ee42c634><p data-v-ee42c634><strong data-v-ee42c634>Aidan Boissonneault</strong></p><p data-v-ee42c634>North Bay, Ontario</p><p data-v-ee42c634>Canada</p></div><h2 id="request" data-v-ee42c634>15. HOW CAN YOU REVIEW, UPDATE, OR DELETE THE DATA WE COLLECT FROM YOU?</h2><p data-v-ee42c634> Based on the applicable laws of your country or state of residence in the US, you may have the right to request access to the personal information we collect from you, details about how we have processed it, correct inaccuracies, or delete your personal information. You may also have the right to withdraw your consent to our processing of your personal information. These rights may be limited in some circumstances by applicable law. To request to review, update, or delete your personal information, please visit: <a href="mailto:tervabrewed@gmail.com" data-v-ee42c634>tervabrewed@gmail.com</a>. </p><p class="generated-by" data-v-ee42c634> This Privacy Policy was created using <a href="https://termly.io/products/privacy-policy-generator/" target="_blank" rel="noopener" data-v-ee42c634>Termly&#39;s Privacy Policy Generator</a>. </p>',73))])}const y=i(u,[["render",p],["__scopeId","data-v-ee42c634"]]);export{y as default};
